(({F:e})=>{e.push({code:"fa",week:{dow:6,doy:12},direction:"rtl",prevText:"قبلی",nextText:"بعدی",prevYearText:"سال قبل",nextYearText:"سال بعد",todayText:"امروز",yearText:"سال",monthText:"ماه",weekTextLong:"هفته",weekTextShort:"هف",dayText:"روز",listText:"برنامه",allDayText:"تمام روز",moreLinkText(e){return"+"+e+" بیشتر"},noEventsText:"هیچ رویدادی برای نمایش یافت نشد",prevHint:"$0 قبلی",nextHint:"$0 بعدی",todayHint(e,t){return"day"===t?"امروز":"year"===t?"امسال":"این "+(e||"دوره")},viewHint:"مشاهده $0",navLinkHint:"برو به $0",closeHint:"بستن",eventsHint:"رویدادها"})})(FullCalendar.Shared);